144			t.Fatalf("修改后订单状态错误: %+v", o)
145		}
146	
147		// 已成交的 1 份只计入持仓：占用现金只按未成交剩余量计（other 1 + target 2 = 3），
148		// 历史成交金额保持不变（现金 7 不因修改重新计价）。
149		if e.Cash() != 7 || e.ReservedCash() != 3 || e.AvailableCash() != 4 || e.Position("A") != M-3 {
150			t.Fatalf("修改后资金与持仓错误: cash=%d reserved=%d available=%d pos=%d",
151				e.Cash(), e.ReservedCash(), e.AvailableCash(), e.Position("A"))
152		}
