156		if _, err := e.Buy("A", 1, 1); !errors.Is(err, ErrInt64Overflow) {
157			t.Fatalf("合计恰好为 M 后再买 1 份应溢出拒绝，实际 %v", err)
158		}
159	
160		// 剩余部分仍可按新参数成交：成交 2 份 @1 后持仓 M-1、现金 5，历史成交不重新计价。
161		if _, err := e.Fill(Trade{TradeID: 4, OrderID: target, Symbol: "A", Side: Buy, Price: 1, Qty: 2}); err != nil {
162			t.Fatalf("修改后剩余部分应能按新参数成交: %v", err)
163		}
164		if e.Cash() != 5 || e.ReservedCash() != 1 || e.Position("A") != M-1 {
165			t.Fatalf("按新参数成交后账目错误: cash=%d reserved=%d pos=%d",
166				e.Cash(), e.ReservedCash(), e.Position("A"))
167		}
168		if o, _ := e.Order(target); o.Status != StatusFilled || o.Filled != 3 {
169			t.Fatalf("target 应全部成交: %+v", o)
170		}
