173	// TestModifyPendingBuyPositionSumOverflow 覆盖待成交买单（无成交）的同类数量溢出：
174	// 把待成交的 other（总量 1、剩余 1）改为总量 4 后，合约合计占用
175	// (M-3)+1(target 剩余)+4 = M+2 超出 int64，必须整体拒绝且保持全部状态。
176	func TestModifyPendingBuyPositionSumOverflow(t *testing.T) {
