type OrderStatus int

const (
	// StatusPending 待成交：订单已接受，尚无成交。
	StatusPending OrderStatus = iota + 1
	// StatusPartial 部分成交。
	StatusPartial
	// StatusFilled 全部成交。
	StatusFilled
	// StatusCanceled 已撤销（可能已有部分成交）。
	StatusCanceled
)

// String 返回状态的中文描述。
func (s OrderStatus) String() string {
	switch s {
	case StatusPending:
		return "待成交"
	case StatusPartial:
		return "部分成交"
	case StatusFilled:
		return "全部成交"
	case StatusCanceled:
		return "已撤销"
	default:
		return "未知状态"
	}
}

