	fmt.Println("冲突后: 最新报价", q.Seq, "缺口", e.HasGap("A"), "现金", e.Cash(),
		"持仓", e.Position("A"), "记录数", len(e.Records()))

	// 缺口期间通过正常卖单卖出全部 2 份。卖单刚被接受、尚未成交时，持仓并不减少，
	// 可卖数量被卖单占用为 0；现金也不预先增加。
