	must(err)
	fmt.Println("卖出成交: 本次", sellRes.Qty, "累计", sellRes.Filled, "剩余", sellRes.Remaining, sellRes.Status)
	q, _ = e.CurrentQuote("A")
	fmt.Println("卖出后: 现金", e.Cash(), "持仓", e.Position("A"), "缺口", e.HasGap("A"), "最新报价", q.Seq)

