		"现金", e.Cash(), "持仓", e.Position("A"))
	fmt.Println("最终: 净值", s.Equity, "亏损", s.Loss, "限制", s.Restricted)

	// 此前的溢出拒绝记录原样保留，卖出与补齐都没有改写它。
	for i, r := range e.Records() {
		fmt.Printf("记录[%d] %s 订单=%d 成交=%d %s\n", i, r.Kind, r.OrderID, r.TradeID, r.Reason)
	}
